CREATE TABLE ZWALIDPROPERTIES ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZDISPLAYNAME VARCHAR, ZLID VARCHAR, ZUSERNAME VARCHAR );
CREATE TABLE ZWALIDTHREADPROPERTIES ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZISSHAREDPHONENUMBER INTEGER, ZTHREADJID VARCHAR );
CREATE TABLE ZWAPHONENUMBERLIDPAIR ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZTIMESTAMP TIMESTAMP, ZLID VARCHAR, ZPHONENUMBER VARCHAR );
CREATE TABLE ZWASINTEROPINTEGRATORPROPERTIES ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZID INTEGER, ZOPTIN INTEGER, ZSTATUS INTEGER, ZUSERIDTYPE INTEGER, ZICONDIRECTPATH VARCHAR, ZNAME VARCHAR, ZADDITIONAL BLOB );
CREATE TABLE ZWAZACCOUNT ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZCURRENTPHONENUMBERSHARINGSTATE INTEGER, ZSTATE INTEGER, ZUSERTYPE INTEGER, ZUSERNAMESTATE INTEGER, ZCREATEDAT TIMESTAMP, ZCOUNTRYCODE VARCHAR, ZDISPLAYNAME VARCHAR, ZIDENTIFIER VARCHAR, ZPHONENUMBER VARCHAR, ZUSERNAME VARCHAR, ZADDITIONALDATA BLOB );
CREATE INDEX Z_WALIDProperties_byLid ON ZWALIDPROPERTIES (ZLID COLLATE BINARY ASC);
CREATE INDEX Z_WALIDProperties_byUsername ON ZWALIDPROPERTIES (ZUSERNAME COLLATE BINARY ASC);
CREATE INDEX Z_WALIDThreadProperties_byThreadJID ON ZWALIDTHREADPROPERTIES (ZTHREADJID COLLATE BINARY ASC);
CREATE INDEX Z_WAPhoneNumberLIDPair_byLidIndex ON ZWAPHONENUMBERLIDPAIR (ZLID COLLATE BINARY ASC);
CREATE INDEX Z_WAPhoneNumberLIDPair_byPhoneNumberIndex ON ZWAPHONENUMBERLIDPAIR (ZPHONENUMBER COLLATE BINARY ASC);
CREATE INDEX Z_WASInteropIntegratorProperties_byID ON ZWASINTEROPINTEGRATORPROPERTIES (ZID COLLATE BINARY ASC);
CREATE INDEX Z_WASInteropIntegratorProperties_byStatus ON ZWASINTEROPINTEGRATORPROPERTIES (ZSTATUS COLLATE BINARY ASC, ZOPTIN COLLATE BINARY ASC);
CREATE UNIQUE INDEX Z_WASInteropIntegratorProperties_UNIQUE_id ON ZWASINTEROPINTEGRATORPROPERTIES (ZID COLLATE BINARY ASC);
CREATE INDEX Z_WAZAccount_byIdentifier ON ZWAZACCOUNT (ZIDENTIFIER COLLATE BINARY ASC);
CREATE INDEX Z_WAZAccount_byPhoneNumber ON ZWAZACCOUNT (ZPHONENUMBER COLLATE BINARY ASC);
CREATE INDEX Z_WAZAccount_byUsername ON ZWAZACCOUNT (ZUSERNAME COLLATE BINARY ASC);
CREATE UNIQUE INDEX Z_WAZAccount_UNIQUE_identifier ON ZWAZACCOUNT (ZIDENTIFIER COLLATE BINARY ASC);
CREATE TABLE Z_PRIMARYKEY (Z_ENT INTEGER PRIMARY KEY, Z_NAME VARCHAR, Z_SUPER INTEGER, Z_MAX INTEGER);
CREATE TABLE Z_METADATA (Z_VERSION INTEGER PRIMARY KEY, Z_UUID VARCHAR(255), Z_PLIST BLOB);
CREATE TABLE Z_MODELCACHE (Z_CONTENT BLOB);
